SELECT ds.* FROM ( SELECT business_date , pbor_node_name , time_weighted_return_local_currency  
FROM performance.scd_performance_bottom_up 
where dataset_id = 'SAP_C' 
and pbor_node_name ='Sustainable Energy Group' ) ds LIMIT 0

